from lib import *
S = SS('k10')
F1 = [['merge patch', '列表整个替换'], ['strategic patch', '按 name 合并'], ['JSON patch', '按下标替换']]
F2 = [['merge: null', '删 key'], ['strategic: $patch: delete', '按 name 删元素'], ['JSON patch: remove', '按下标删'], ['JSON patch: test', '不符就整体拒绝']]
F3 = [['containers / env / volumes', 'merge key = name'], ['ports', 'merge key = containerPort'], ['tolerations / command / args', 'atomic,整个替换']]
F4 = [['strategic', '415 不支持'], ['merge', '列表整个替换'], ['json', '按下标']]
PANELS = [('f', 'flow', 'patch 的合并规则'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("三种 patch 都想“把容器 a 的镜像改成 busybox:1.35”。merge patch:containers 整个列表被替换,结果只剩 a,而且 a 的 command 变成 null、env 为空,容器 b 没了;strategic merge patch:按 name 合并,a 的 image 变了,command、env 都保留,b 不动;JSON patch(按下标 containers/0/image):同样只改 image。merge patch 即使把 a 的 image 和 command 写全,b 仍然丢失。", f=fl(F1, cur=[0], done=[1, 2]), t=tl(S(1), mark=lidx(S(1), '--type=merge', '"command": null', '仍然被整个列表替换掉了'), done=lidx(S(1), '--type=strategic', '--type=json')), kv=KV([['merge patch', '列表是原子的,整个替换'], ['strategic', '列表里的元素按 merge key 合并'], ['JSON patch', '精确到下标,但下标会变']], ['merge patch'])),
    step("删除:merge patch 把 annotation drop 设成 null 就删掉它;strategic 用 {name: b, $patch: delete} 删掉容器 b,用 {name: X, $patch: delete} 删掉容器 a 的 env X;JSON patch remove containers/0 删掉的是第一个容器 a(下标);先 test containers/0/name==b 再 remove,test 不符时整个 patch 被拒绝(退出码 1)。", f=fl(F2, cur=[1], mark=[2], done=[0, 3]), t=tl(S(2), mark=lidx(S(2), 'remove containers/0', '下标和预期不符'), done=lidx(S(2), '设为 null', '$patch: delete')), kv=KV([['null', 'merge patch 里表示删除'], ['$patch: delete', 'strategic 里按 key 删元素'], ['JSON patch 的 test', '给按下标的修改加前置条件']], ['JSON patch 的 test'])),
    step("schema 里的扩展决定了列表怎么合并:PodSpec.containers、Container.env 的 merge key 是 name,volumes 还多了 retainKeys,ports 是 containerPort;tolerations、command、args 是 atomic——strategic patch 写一条 t3,tolerations 就从 [t1, t2] 变成只有 [t3]。", f=fl(F3, cur=[2], done=[0, 1]), t=tl(S(3), mark=lidx(S(3), 'tolerations', 'Container.command', '写一条 t3'), done=lidx(S(3), 'PodSpec.containers', 'Container.env', 'Container.ports')), kv=KV([['x-kubernetes-patch-merge-key', '合并列表时用哪个字段对齐元素'], ['atomic', '写什么就是什么,整个替换'], ['strategic patch 的用武之地', '只对内置资源有意义']], ['atomic'])),
    step("自定义资源:--type=strategic → 退出码 1,application/strategic-merge-patch+json is not supported by k10.example.com/v1, Kind=Box,并列出可接受的媒体类型;--type=merge → spec.items 整个被替换,只剩 [{first, 9}];--type=json 按下标把 items/0/v 改成 9,第二个元素保留。", f=fl(F4, cur=[0], mark=[1], done=[2]), t=tl(S(4), mark=lidx(S(4), '--type=strategic'), done=lidx(S(4), '--type=json')), kv=KV([['CRD', '不支持 strategic merge patch'], ['merge patch', '列表整个替换'], ['想精确改列表元素', 'JSON patch 或 server-side apply']], ['CRD'])),
]
A = mkartk('k10', 10, 'Kubernetes,patch,strategic merge patch,JSON merge patch,JSON patch,真实验证,动画演示',
    '在 kind 集群里用同一个修改对比三种 patch:merge patch 把 containers 列表整个替换(丢掉容器 b 和 a 的 command),strategic merge patch 按 name 合并只改 image,JSON patch 按下标精确修改;null、$patch: delete、JSON patch 的 remove 与 test 各自怎么删;schema 里的 x-kubernetes-patch-merge-key 决定了 containers、env、ports 按 key 合并而 tolerations、command 整个替换;自定义资源不支持 strategic merge patch。',
    'kubectl patch --type 的三个取值看似差不多,改容器列表时结果却天差地别。这篇用同一个目标跑三种 patch,看列表是被合并还是被整个替换,再看删除怎么写、哪些字段会按 key 合并、自定义资源能用哪几种。',
    [('3 种结果', '同一个“改容器 a 的镜像”在 merge、strategic、JSON patch 下得到的不同对象'), ('[t3]', 'strategic patch 往 tolerations 写一条 t3 之后列表的内容(原来是 [t1, t2])'), ('415', '对自定义资源用 --type=strategic 的结果:application/strategic-merge-patch+json is not supported')],
    [('同一个修改,三种结果', '<p>目标都是“把容器 a 的镜像改成 busybox:1.35”。<b>merge patch</b>(RFC 7386)把整个 <code>containers</code> 列表当成一个值替换:结果只剩 a,a 的 <code>command</code> 丢了(<code>null</code>),容器 b 不见了;就算把 a 的 image 和 command 写全,b 也回不来。<b>strategic merge patch</b>(kubectl 对内置资源的默认类型)按 <code>name</code> 对齐列表元素,只改 a 的 image,其余都保留。<b>JSON patch</b>(RFC 6902)按下标 <code>containers/0/image</code> 精确修改,同样只动 image。</p>'),
     ('怎么删', '<p>merge patch 里把某个 key 设为 <code>null</code> 就是删除(这里删掉了注解 <code>drop</code>);strategic 里用 <code>$patch: delete</code> 按 key 删列表元素(删掉容器 b,或容器 a 里的 env X);JSON patch 用 <code>remove</code> + 下标,下标一错删掉的就是别的元素(<code>containers/0</code> 删掉的是 a)。JSON patch 可以先加一个 <code>test</code> 操作做前置条件,条件不符整个 patch 被拒绝(这次退出码 1)。</p>'),
     ('哪些列表按 key 合并', '<p>策略取决于 schema 里的扩展:<code>containers</code> 和 <code>env</code> 的 <code>x-kubernetes-patch-merge-key</code> 是 <code>name</code>,<code>ports</code> 是 <code>containerPort</code>,<code>volumes</code> 的策略是 <code>merge,retainKeys</code>;而 <code>tolerations</code>、<code>command</code>、<code>args</code> 只有 <code>x-kubernetes-list-type: atomic</code>,strategic patch 写一条 <code>t3</code>,<code>tolerations</code> 就从 [t1, t2] 变成只有 [t3]。</p>'),
     ('自定义资源', '<p>CRD 没有 Go 结构体上的 patchStrategy 标记,所以不支持 strategic merge patch:<code>--type=strategic</code> 得到 <code>application/strategic-merge-patch+json is not supported by k10.example.com/v1, Kind=Box</code>,并列出可接受的媒体类型(其中有 application/json-patch+json、application/merge-patch+json)。对自定义资源,merge patch 同样整个替换列表;要精确改列表元素,用 JSON patch 或 server-side apply(前提是 CRD 里声明了 <code>x-kubernetes-list-type: map</code>)。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);Deployment web(replicas=0,两个 busybox:1.36 容器 a、b,a 带 command 和 env X,两条 tolerations)每个用例前重新创建;patch 用 kubectl patch --type=merge|strategic|json;merge key 信息取自 /openapi/v3/apis/apps/v1 里 PodSpec 与 Container 的 schema 扩展;自定义资源是 boxes.k10.example.com(x-kubernetes-preserve-unknown-fields);每种情形各一次',
     '没有验证:strategic merge patch 的 $setElementOrder、$retainKeys、$deleteFromPrimitiveList 指令;JSON patch 的 add/move/copy 操作;patch 与 server-side apply(--type=apply-patch)的混用;对 status 子资源的 patch;大对象 patch 的性能;kubectl patch 的 --patch-file 与 -f 形式'],
    '三种 patch', PANELS)
